: "layering-idle.inter-rat", "category_id": "layering-idle", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: systemInformation/systemInformation-r8/sib-TypeAndInfo/[*]/sib7"}, {"technology": "LTE", "path_prefix": "systemInformation/systemInformation-r8/sib-TypeAndInfo/[*]/sib7/carrierFreqsInfoList/[*]/commonInfo/threshX-Low", "subcategory_id": "layering-idle.inter-rat", "category_id": "layering-idle", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: systemInformation/systemInformation-r8/sib-TypeAndInfo/[*]/sib7"}, {"technology": "LTE", "path_prefix": "systemInformation/systemInformation-r8/sib-TypeAndInfo/[*]/sib7/t-ReselectionGERAN", "subcategory_id": "layering-idle.inter-rat", "category_id": "layering-idle", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: systemInformation/systemInformation-r8/sib-TypeAndInfo/[*]/sib7"}, {"technology": "NR", "path_prefix": "mib/cellBarred", "subcategory_id": "layering-idle.access", "category_id": "layering-idle", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: mib/cellBarred"}, {"technology": "NR", "path_prefix": "mib/dmrs-TypeA-Position", "subcategory_id": "phy.reference", "category_id": "phy", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: mib/dmrs-TypeA-Position"}, {"technology": "NR", "path_prefix": "mib/intraFreqReselection", "subcategory_id": "layering-idle.access", "category_id": "layering-idle", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: mib/intraFreqReselection"}, {"technology": "NR", "path_prefix": "mib/ssb-SubcarrierOffset", "subcategory_id": "phy.carrier", "category_id": "phy", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: mib/ssb-SubcarrierOffset"}, {"technology": "NR", "path_prefix": "mib/subCarrierSpacingCommon", "subcategory_id": "phy.carrier", "category_id": "phy", "discriminator": {}, "note": "Spécification utilisateur dict_categories (inline), contexte ASN.1 vérifié dans paths.csv ; préfixe de contexte: mib/subCarrierSpacingCommon"}]'::jsonb)
 AS m(technology text,path_prefix text,category_id text,subcategory_id text,discriminator jsonb,note text)
), eligible AS (
 SELECT *,regexp_replace(path,'\[[0-9]+\]','[*]','g') AS normalized
 FROM param_occurrence WHERE project_id='134af70a06eb'
 AND origin='network_config' AND param_key IS NOT NULL AND NOT COALESCE(is_identifier,false)
 AND NOT(regexp_replace(path,'^.*/','') ~ '^(spare[0-9]*|dummy|reserved)$')
), classified AS (
 SELECT e.*,m.category_id,m.subcategory_id FROM eligible e
 LEFT JOIN LATERAL(
 SELECT category_id,subcategory_id FROM mappings m
 WHERE m.technology IN(e.system,'BOTH')
 AND (e.normalized=m.path_prefix OR starts_with(e.normalized,m.path_prefix||'/'))
 AND COALESCE(e.discriminators,'{}'::jsonb) @> m.discriminator
 ORDER BY length(m.path_prefix) DESC,(SELECT count(*) FROM jsonb_object_keys(m.discriminator)) DESC,
 (m.technology=e.system) DESC LIMIT 1
 ) m ON true
), keys AS (
 SELECT system,param_key,bool_and(category_id IS NOT NULL) fully_mapped,
 bool_or(category_id IS NULL) unresolved,bool_or(category_id='autres') explicit_autres
 FROM classified GROUP BY system,param_key
)

SELECT count(*) eligible_keys,count(*) FILTER(WHERE fully_mapped) fully_mapped_keys,
count(*) FILTER(WHERE unresolved) unresolved_keys,count(*) FILTER(WHERE explicit_autres) explicit_autres_keys,
round(100.0*count(*) FILTER(WHERE unresolved OR explicit_autres)/NULLIF(count(*),0),2) unresolved_or_autres_pct,
(SELECT count(*) FROM classified) eligible_occurrences,
(SELECT count(*) FROM classified WHERE category_id IS NULL) unresolved_occurrences
FROM keys;
